/** Case-insensitive monster lookup by name. */
export function getMonsterByName(name: string): Monster | null {
  const lower = name.toLowerCase();
  // Try direct key lookup first
  const key = lower.replace(/\s+/g, "-");
  if (MONSTER_DB[key]) return MONSTER_DB[key];
  // Fall back to scanning names
  for (const monster of Object.values(MONSTER_DB)) {
    if (monster.name.toLowerCase() === lower) return monster;
  }
  return null;
}

/** Get all monsters of a given challenge rating. */
export function getMonstersByCR(cr: number): Monster[] {
  return Object.values(MONSTER_DB).filter(m => m.cr === cr);
}
